            let isAuthor = baseUrl.match(new RegExp(pattern))
            if (isAuthor) {
                java.log(`作者ID：${id}`)
                novelId = getAjaxJson(urlUserDetailed(id)).novels.reverse()[0]
                java.log(`最新一篇小说ID：${novelId}`)
            }

            pattern = "(https?://)?(api\\.|www\\.)?(linpx\\.ink)/(pn|pixiv/novel)/\\d+(/cache)?"
